const red = new Set([1, 2, 3, 4]);
const blue = new Set([3, 4, 5]);

console.log([...red.difference(blue)].join(","));
console.log([...blue.difference(red)].join(","));
console.log([...blue.symmetricDifference(red)].join(","));
console.log([...blue.union(red)].join(","));
